"""
Flat-file (JSON) storage for the Task Management API.

No database is used — tasks persist to a single JSON file on disk. Writes are
atomic (write to a temp file, then os.replace) and serialized with a lock so
concurrent requests within one process don't corrupt the file.
"""

import json
import os
import threading
from datetime import datetime


def _now_iso() -> str:
    # Always include microseconds (fixed width) so plain string comparison
    # sorts chronologically, e.g. for "ORDER BY created_at desc".
    return datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S.%f")


class TaskStore:
    def __init__(self, path: str):
        self.path = path
        self._lock = threading.Lock()
        if not os.path.exists(self.path):
            self._write({"next_id": 1, "tasks": []})

    def _read(self) -> dict:
        with open(self.path, "r") as f:
            return json.load(f)

    def _write(self, data: dict) -> None:
        tmp_path = f"{self.path}.tmp"
        with open(tmp_path, "w") as f:
            json.dump(data, f, indent=2)
        os.replace(tmp_path, self.path)

    def create(self, title: str) -> dict:
        with self._lock:
            data = self._read()
            task = {
                "id": data["next_id"],
                "title": title,
                "status": "pending",
                "created_at": _now_iso(),
            }
            data["tasks"].append(task)
            data["next_id"] += 1
            self._write(data)
            return task

    def list_all(self) -> list:
        data = self._read()
        return sorted(data["tasks"], key=lambda t: t["created_at"], reverse=True)

    def get(self, task_id: int) -> dict | None:
        data = self._read()
        for task in data["tasks"]:
            if task["id"] == task_id:
                return task
        return None

    def update(self, task_id: int, title: str | None = None, status: str | None = None) -> dict | None:
        with self._lock:
            data = self._read()
            for task in data["tasks"]:
                if task["id"] == task_id:
                    if title is not None:
                        task["title"] = title
                    if status is not None:
                        task["status"] = status
                    self._write(data)
                    return task
            return None

"""
Flask API for task management.

Storage is flat-file JSON (see storage.py) — no database is used, per the
project's storage constraint.
"""

import os

from flask import Flask, jsonify, request

from storage import TaskStore

DEFAULT_STORAGE_PATH = os.environ.get("TASKS_STORAGE_PATH", "tasks.json")


def create_app(storage_path: str = DEFAULT_STORAGE_PATH) -> Flask:
    app = Flask(__name__)
    app.store = TaskStore(storage_path)

    @app.errorhandler(404)
    def not_found(_e):
        return jsonify({"error": "not found"}), 404

    @app.post("/tasks")
    def create_task():
        data = request.get_json(silent=True) or {}
        title = data.get("title")
        if not isinstance(title, str) or not title.strip():
            return jsonify({"error": "title is required"}), 400
        task = app.store.create(title.strip())
        return jsonify(task), 201

    @app.get("/tasks")
    def list_tasks():
        return jsonify(app.store.list_all()), 200

    @app.get("/tasks/<int:task_id>")
    def get_task(task_id):
        task = app.store.get(task_id)
        if task is None:
            return jsonify({"error": "task not found"}), 404
        return jsonify(task), 200

    @app.put("/tasks/<int:task_id>")
    def update_task(task_id):
        data = request.get_json(silent=True) or {}
        title = data.get("title")
        status = data.get("status")

        if "title" not in data and "status" not in data:
            return jsonify({"error": "title or status is required"}), 400
        if title is not None and (not isinstance(title, str) or not title.strip()):
            return jsonify({"error": "title must be a non-empty string"}), 400
        if status is not None and (not isinstance(status, str) or not status.strip()):
            return jsonify({"error": "status must be a non-empty string"}), 400

        task = app.store.update(
            task_id,
            title=title.strip() if title is not None else None,
            status=status.strip() if status is not None else None,
        )
        if task is None:
            return jsonify({"error": "task not found"}), 404
        return jsonify(task), 200

    return app


if __name__ == "__main__":
    app = create_app()
    app.run(debug=True)
